using System.ComponentModel.DataAnnotations;using Essco.Application.Products;using Essco.Application.Security;using Essco.Domain.Products;using Microsoft.AspNetCore.Authorization;using Microsoft.AspNetCore.Mvc;using Microsoft.AspNetCore.Mvc.RazorPages;namespace Essco.Web.Pages.Products;[Authorize(Policy=Permissions.Billing)]public sealed class DiscountsModel(ProductService service):PageModel{[BindProperty]public InputModel Input{get;set;}=new();public IReadOnlyCollection<AutomaticDiscount>Items{get;private set;}=[];[TempData]public string?StatusMessage{get;set;}public async Task OnGetAsync(string?edit,CancellationToken t){Items=await service.ListDiscountsAsync(t);var x=Items.FirstOrDefault(x=>x.ProductCode==edit);if(x is not null)Input=InputModel.From(x);}public async Task<IActionResult>OnPostSaveAsync(CancellationToken t){if(ModelState.IsValid){var r=await service.SaveDiscountAsync(Input.Domain(),Input.IsNew,t);if(r.Succeeded){StatusMessage="Descuento guardado.";return RedirectToPage();}foreach(var e in r.Errors)ModelState.AddModelError("",e);}Items=await service.ListDiscountsAsync(t);return Page();}public async Task<IActionResult>OnPostDeleteAsync(string code,CancellationToken t){StatusMessage=await service.DeleteDiscountAsync(code,t)?"Descuento eliminado.":"No existe.";return RedirectToPage();}public sealed class InputModel{public bool IsNew{get;set;}=true;[Required]public string ProductCode{get;set;}="";public string Description{get;set;}="";public decimal Percentage{get;set;}[DataType(DataType.Date)]public DateOnly From{get;set;}=DateOnly.FromDateTime(DateTime.Today);[DataType(DataType.Date)]public DateOnly To{get;set;}=DateOnly.FromDateTime(DateTime.Today);public decimal MinimumQuantity{get;set;}public decimal AvailableQuantity{get;set;}public string Comments{get;set;}="";public AutomaticDiscount Domain()=>new(){ProductCode=ProductCode,Description=Description,Percentage=Percentage,From=From,To=To,MinimumQuantity=MinimumQuantity,AvailableQuantity=AvailableQuantity,Comments=Comments};public static InputModel From(AutomaticDiscount x)=>new(){IsNew=false,ProductCode=x.ProductCode,Description=x.Description,Percentage=x.Percentage,From=x.From,To=x.To,MinimumQuantity=x.MinimumQuantity,AvailableQuantity=x.AvailableQuantity,Comments=x.Comments};}}
